<template><main class="login-page"><form class="login-card" @submit.prevent="login"><p class="eyebrow">SMARTQA / TENANT OPS</p><h1>进入智能问答<br><em>SaaS 管理台</em></h1><label>用户名<input v-model.trim="username" autocomplete="username" /></label><label>密码<input v-model="password" type="password" autocomplete="current-password" /></label><label>租户编码（可选）<input v-model.trim="tenantCode" /></label><button class="primary" :disabled="loading">{{ loading ? '登录中…' : '登录' }}</button><p v-if="error" class="error">{{ error }}</p></form></main></template>
<script setup>
import { ref } from 'vue'; import { useRouter } from 'vue-router'
import { defaultRouteForRole } from '../auth'
const router = useRouter(), username = ref(''), password = ref(''), tenantCode = ref(''), loading = ref(false), error = ref('')
async function login() { if (!username.value || !password.value) return error.value = '请输入用户名和密码'; loading.value = true; error.value = ''; try { const r = await fetch('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: username.value, password: password.value, tenant_code: tenantCode.value || undefined }) }); const b = await r.json(); if (!r.ok) throw new Error(b.message || '登录失败'); const identity = b.data; localStorage.setItem('smartqa_token', identity.access_token); localStorage.setItem('smartqa_role', identity.role); localStorage.setItem('smartqa_username', identity.username); localStorage.setItem('smartqa_tenant', identity.tenant_code); await router.replace(identity.home || defaultRouteForRole(identity.role)) } catch (e) { error.value = e.message } finally { loading.value = false } }
</script>
